# PyTorch-এর nn.Module ও Parameter Registration কীভাবে ভেতরে কাজ করে (Pure Python মিনি Registry!)
class SimpleParameter:
    def __init__(self, shape, name=""):
        self.shape = shape
        self.name = name

    def numel(self):
        total = 1
        for dim in self.shape:
            total *= dim
        return total


class SimpleLinear:
    def __init__(self, in_features, out_features):
        # PyTorch প্রথায় Weight Shape হলো [out_features, in_features]!
        self.weight = SimpleParameter((out_features, in_features), "weight")
        self.bias = SimpleParameter((out_features,), "bias")

    def named_parameters(self, prefix=""):
        return [
            (prefix + "weight", self.weight),
            (prefix + "bias", self.bias),
        ]


class SimpleModule:
    def __init__(self):
        self._modules = {}
        self._buffers = {}

    def register_module(self, name, mod):
        self._modules[name] = mod

    def register_buffer(self, name, values):
        # Buffer হলো Non-trainable কিন্তু state_dict-এ থাকে!
        self._buffers[name] = values

    def named_parameters(self):
        result = []
        for mod_name in self._modules:
            mod = self._modules[mod_name]
            for p_name, param in mod.named_parameters(prefix=mod_name + "."):
                result.append((p_name, param))
        return result

    def state_dict_keys(self):
        keys = []
        for p_name, _ in self.named_parameters():
            keys.append(p_name)
        for buf_name in self._buffers:
            keys.append(buf_name)
        return keys


# ১) সঠিকভাবে নিবন্ধিত TinyMLP -> ঠিক 53 Parameter!
mlp = SimpleModule()
mlp.register_module("hidden", SimpleLinear(11, 4))
mlp.register_module("output", SimpleLinear(4, 1))
mlp.register_buffer("scaler_mean", [0.0] * 11)

total = 0
param_names = []
for name, p in mlp.named_parameters():
    total += p.numel()
    param_names.append(f"{name}:{p.shape}")

assert total == 53
print("Registered Params:", param_names)
print("Total Trainable Parameters:", total)
print("state_dict keys (includes buffer!):", mlp.state_dict_keys())

# ২) সাধারণ Python list-এ Layer রাখলে কী বাগ হয় তার প্রতীকী প্রমাণ:
unregistered_list = [SimpleLinear(4, 4), SimpleLinear(4, 4)]
buggy_mlp = SimpleModule()
buggy_mlp.plain_layers = unregistered_list  # register_module না হওয়ায় _modules খালি!
print("Buggy Python-list Module param count:", len(buggy_mlp.named_parameters()), "(সব হারিয়ে গেছে!)")
